set -e
mkdir -p ~/.claude/hooks ~/.claude/scripts/lib
cd ~/src
for h in pre-edit-guard pre-bash-codex-launch-guard stop-guard user-prompt-review-guard; do cp hooks/$h.sh ~/.claude/hooks/; chmod +x ~/.claude/hooks/$h.sh; done
cp scripts/review-state.js ~/.claude/scripts/; cp scripts/lib/tree-digest.js ~/.claude/scripts/lib/
H=/home/runner/.claude/hooks
cat > ~/.claude/settings.json <<EOF
{
  "hooks": {
    "PreToolUse": [
      { "matcher": "Edit|Write|NotebookEdit", "hooks": [ { "type": "command", "command": "$H/pre-edit-guard.sh" } ] },
      { "matcher": "Bash", "hooks": [ { "type": "command", "command": "$H/pre-bash-codex-launch-guard.sh" } ] }
    ],
    "Stop": [
      { "matcher": "", "hooks": [ { "type": "command", "command": "$H/stop-guard.sh" } ] }
    ],
    "UserPromptSubmit": [
      { "matcher": "", "hooks": [ { "type": "command", "command": "$H/user-prompt-review-guard.sh" } ] }
    ]
  }
}
EOF
jq . ~/.claude/settings.json >/dev/null && echo ok
cd /tmp && printf '{"tool_input":{"file_path":"/tmp/x/.env"}}' | CLAUDE_PROJECT_DIR=/tmp $H/pre-edit-guard.sh; echo rc=$?
printf '{"tool_input":{"file_path":"/tmp/x/a.txt"}}' | CLAUDE_PROJECT_DIR=/tmp $H/pre-edit-guard.sh; echo rc=$?
node -e 'require("/home/runner/.claude/scripts/review-state.js")' --help >/dev/null 2>&1; echo node_rc=$?

